<template><div class="member-picker"><div class="selected" v-if="selected.length"><span v-for="member in selected" :key="member.id" class="chip"><span class="chip-avatar">{{(member.name||'?').slice(0,1)}}</span><span>{{member.name}}</span><button type="button" @click="toggle(member)"><img :src="closeIcon" alt="" /></button></span></div><div class="member-list"><button v-for="member in members" :key="member.id" class="member-row" type="button" @click="toggle(member)"><span class="avatar">{{(member.name||'?').slice(0,1)}}</span><span class="name">{{member.name}}</span><span class="indicator" :class="{selected:isSelected(member),radio:!multiple}">{{isSelected(member)?'✓':''}}</span></button></div></div></template>
<script setup>import{computed}from'vue';import closeIcon from '../../assets/figma-close-circle.svg';const props=defineProps({members:{type:Array,default:()=>[]},modelValue:{type:Array,default:()=>[]},multiple:Boolean});const emit=defineEmits(['update:modelValue','change']);const selected=computed(()=>props.members.filter(x=>props.modelValue.includes(x.id)));function isSelected(x){return props.modelValue.includes(x.id)}function toggle(x){const next=isSelected(x)?props.modelValue.filter(id=>id!==x.id):(props.multiple?[...props.modelValue,x.id]:[x.id]);emit('update:modelValue',next);emit('change',next)}</script>
<style scoped>.member-picker{width:100%;color:#1D2129}.selected{display:flex;flex-wrap:wrap;gap:8px;padding:4px 0 12px}.chip{min-height:28px;padding:4px 8px;display:inline-flex;align-items:center;gap:4px;border:1px solid #E5E6EB;border-radius:40px;background:#fff;font:400 12px/20px "PingFang SC",sans-serif}.chip-avatar,.avatar{display:inline-flex;align-items:center;justify-content:center;border-radius:50%;color:#fff;background:#C9CDD4}.chip-avatar{width:16px;height:16px;font-size:10px}.chip button{width:14px;height:14px;padding:0;border:0;background:transparent}.chip button img{display:block;width:14px;height:14px}.member-list{display:flex;flex-direction:column}.member-row{min-height:56px;padding:8px 0;display:flex;align-items:center;gap:12px;border:0;border-bottom:1px solid #F2F3F5;background:#fff;text-align:left}.avatar{width:24px;height:24px;flex:0 0 24px;font-size:12px}.name{flex:1;font-size:14px;line-height:20px}.indicator{width:14px;height:14px;display:flex;align-items:center;justify-content:center;border:2px solid #E5E6EB;border-radius:2px;color:#fff;background:#fff;font-size:10px}.indicator.radio{border-radius:50%}.indicator.selected{border-color:#00AAA6;background:#00AAA6}</style>
